const body = $input.first().json.body;
const required = ['topic', 'report_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const reportTypes = ['market_analysis','competitive_landscape','industry_overview','technology_assessment','investment_thesis','due_diligence','trend_report','feasibility_study','background_brief'];
const reportType = reportTypes.includes(body.report_type) ? body.report_type : 'background_brief';
const audiences = ['executive','investor','technical','general_business','board'];
const audience = audiences.includes(body.audience) ? body.audience : 'general_business';
return [{ json: { valid: true, topic: body.topic.trim(), reportType, audience, specificQuestions: Array.isArray(body.specific_questions)?body.specific_questions.slice(0,8):(body.specific_questions||'').split('\n').map(q=>q.trim()).filter(Boolean).slice(0,8), scope: (body.scope||'').slice(0,400), geographicFocus: body.geographic_focus||'global', timeframe: body.timeframe||'current', depthLevel: body.depth_level||'comprehensive', excludeTopics: (body.exclude_topics||'').slice(0,200), replyEmail: body.reply_email||null, requestedAt: new Date().toISOString() } }];

const primary = $('Primary Research').first().json?.results || [];
const data = $('Data Research').first().json?.results || [];
const input = $('Validate Input').first().json;
const primaryContext = primary.map(r => `Title: ${r.title}
Source: ${r.url}
Content: ${(r.content||r.snippet||'').slice(0,500)}`).join('

---

');
const dataContext = data.map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,400)}`).join('

');
const sources = [...primary, ...data].map(r => ({ title: r.title, url: r.url }));
return [{ json: { input, primaryContext, dataContext, sources } }];

values.content:
Write a research report.

Topic: {{ $json.input.topic }}
Report type: {{ $json.input.reportType.replace(/_/g,' ') }}
Audience: {{ $json.input.audience.replace(/_/g,' ') }}
Geographic focus: {{ $json.input.geographicFocus }}
Timeframe: {{ $json.input.timeframe }}
Scope: {{ $json.input.scope || 'not specified' }}
Specific questions: {{ $json.input.specificQuestions.join('; ') || 'none specified' }}

Primary research:
{{ $json.primaryContext }}

Data research:
{{ $json.dataContext }}

Return this JSON:
{
  "report_title": "clear, specific title",
  "executive_summary": "3-5 sentences",
  "key_findings": [{"finding":"...","evidence":"...","implication":"..."}],
  "sections": [{"title":"...","content":"..."}],
  "data_highlights": [{"metric":"...","context":"...","source_hint":"..."}],
  "opportunities": ["..."],
  "risks_and_challenges": ["..."],
  "conclusions": "2-3 sentences",
  "recommended_next_steps": ["..."],
  "knowledge_gaps": ["..."]
}

