const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let report;
try { report = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
const merged = $('Merge Research').first().json;
report.sources_used = (merged.sources||[]).slice(0,12);
report._meta = { topic: input.topic, reportType: input.reportType, audience: input.audience, replyEmail: input.replyEmail, generatedAt: new Date().toISOString() };
return [{ json: report }];

const r = $input.first().json;
const m = r._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const sectionBlocks = (r.sections||[]).map(s => `<div style="margin-bottom:24px"><h2 style="font-size:16px;font-weight:700;color:#1e293b;border-bottom:2px solid #e5e7eb;padding-bottom:6px;margin-bottom:12px">${esc(s.title)}</h2><div style="font-size:14px;line-height:1.85;color:#374151;white-space:pre-line">${esc(s.content)}</div></div>`).join('');
const keyFindings = (r.key_findings||[]).map((f,i) => `<div style="border-left:3px solid #2563eb;padding:12px 16px;background:#f8faff;border-radius:0 6px 6px 0;margin-bottom:10px"><div style="font-size:14px;font-weight:600;color:#1e3a8a;margin-bottom:4px">${i+1}. ${esc(f.finding)}</div><div style="font-size:13px;color:#555;margin-bottom:3px">${esc(f.evidence)}</div><div style="font-size:13px;color:#16a34a;font-style:italic">→ ${esc(f.implication)}</div></div>`).join('');
const dataHighlights = (r.data_highlights||[]).map(d => `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:12px 16px;margin-bottom:8px"><div style="font-size:16px;font-weight:700;color:#1e293b">${esc(d.metric)}</div><div style="font-size:13px;color:#6b7280;margin-top:3px">${esc(d.context)}</div><div style="font-size:11px;color:#9ca3af;margin-top:2px">${esc(d.source_hint||'')}</div></div>`).join('');
const opportunities = (r.opportunities||[]).map(o => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #f0fdf4;color:#166534">↑ ${esc(o)}</div>`).join('');
const risks = (r.risks_and_challenges||[]).map(risk => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #fff7ed;color:#c2410c">↓ ${esc(risk)}</div>`).join('');
const nextSteps = (r.recommended_next_steps||[]).map((s,i) => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">${i+1}. ${esc(s)}</div>`).join('');
const gaps = (r.knowledge_gaps||[]).map(g => `<div style="font-size:13px;color:#6b7280;padding:4px 0">◦ ${esc(g)}</div>`).join('');
const sources = (r.sources_used||[]).slice(0,12).map((s,i) => `<div style="font-size:12px;padding:5px 0;border-bottom:1px solid #f3f4f6"><span style="color:#9ca3af;margin-right:6px">[${i+1}]</span><a href="${esc(s.url)}" style="color:#2563eb;text-decoration:none">${esc(s.title)}</a></div>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(r.report_title)}</title></head><body style="margin:0;padding:16px;background:#f5f5f0;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a"><div style="max-width:760px;margin:0 auto"><div style="background:#1e293b;color:#fff;padding:24px 32px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:6px">${esc(m.reportType.replace(/_/g,' '))} · ${esc(m.audience.replace(/_/g,' '))} audience</div><div style="font-size:22px;font-weight:700;line-height:1.3">${esc(r.report_title)}</div><div style="font-size:12px;color:#94a3b8;margin-top:6px;font-family:sans-serif">Generated ${esc(m.generatedAt.split('T')[0])}</div></div><div style="background:#f0f7ff;padding:20px 32px;border:1px solid #bfdbfe;border-top:none"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px;font-family:sans-serif">Executive Summary</div><p style="font-size:15px;line-height:1.85;color:#1e3a8a;margin:0">${esc(r.executive_summary)}</p></div>${keyFindings?`<div style="background:#fff;padding:20px 32px;border:1px solid #e5e7eb;border-top:none"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:12px;font-family:sans-serif">Key Findings</div>${keyFindings}</div>`:''}${dataHighlights?`<div style="background:#f8f8f6;padding:18px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px;font-family:sans-serif">Data Highlights</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px">${dataHighlights}</div></div>`:''}<div style="background:#fff;padding:24px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">${sectionBlocks}</div>${opportunities||risks?`<div style="background:#fff;padding:18px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0"><div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">${opportunities?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:8px;font-family:sans-serif">Opportunities</div>${opportunities}</div>`:''}${risks?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#c2410c;margin-bottom:8px;font-family:sans-serif">Risks & Challenges</div>${risks}</div>`:''}</div></div>`:''}<div style="background:#fff;padding:18px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px;font-family:sans-serif">Conclusions</div><p style="font-size:14px;line-height:1.8;color:#374151;margin:0;font-style:italic">${esc(r.conclusions)}</p></div>${nextSteps?`<div style="background:#eff6ff;padding:16px 32px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px;font-family:sans-serif">Recommended Next Steps</div>${nextSteps}</div>`:''}${gaps?`<div style="background:#f9fafb;padding:14px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px;font-family:sans-serif">Knowledge Gaps & Uncertainties</div>${gaps}</div>`:''}${sources?`<div style="background:#fff;padding:14px 32px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px;font-family:sans-serif">Sources</div>${sources}</div>`:''}<div style="background:#1e293b;color:#475569;font-size:11px;padding:12px 32px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Research Report · ${esc(m.topic)} · ${esc(m.generatedAt.split('T')[0])}</div></div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, reportTitle: r.report_title, topic: m.topic, report: r } }];
